import { View } from "@514labs/moose-lib";

export interface TopProducts {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const TopProductsView = new View<TopProducts>({
  name: "TopProducts",
  query: `
    SELECT
      product_id,
      countIf(event_type = 'view') as view_count,
      countIf(event_type = 'cart') as cart_count,
      countIf(event_type = 'purchase') as purchase_count,
      sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') as total_revenue
    FROM currentDatabase().ProductEvent
    GROUP BY product_id
    ORDER BY total_revenue DESC
  `,
  materialized: {
    enabled: true
  }
});

