const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

// Create SQLite database and tables
const db = new sqlite3.Database(':memory:');

// Initialize database schema
db.serialize(() => {
  // Main events table
  db.run(`CREATE TABLE ProductEvent (
    event_id TEXT PRIMARY KEY,
    event_ts DATETIME,
    user_id TEXT,
    product_id TEXT,
    event_type TEXT,
    properties TEXT
  )`);

  // Materialized views (simulated as regular tables that get updated)
  db.run(`CREATE TABLE TopProducts (
    product_id TEXT PRIMARY KEY,
    view_count INTEGER DEFAULT 0,
    cart_count INTEGER DEFAULT 0,
    purchase_count INTEGER DEFAULT 0,
    total_revenue REAL DEFAULT 0
  )`);

  db.run(`CREATE TABLE ConversionFunnel (
    step TEXT PRIMARY KEY,
    unique_users INTEGER DEFAULT 0,
    total_events INTEGER DEFAULT 0
  )`);

  db.run(`CREATE TABLE HourlyActivity (
    hour TEXT,
    event_type TEXT,
    event_count INTEGER DEFAULT 0,
    PRIMARY KEY (hour, event_type)
  )`);

  // Initialize funnel steps
  db.run(`INSERT INTO ConversionFunnel (step, unique_users, total_events) VALUES
    ('view', 0, 0), ('cart', 0, 0), ('purchase', 0, 0)`);
});

// Function to update materialized views
function updateViews(callback) {
  db.serialize(() => {
    // Update TopProducts
    db.run(`DELETE FROM TopProducts`);
    db.run(`INSERT INTO TopProducts (product_id, view_count, cart_count, purchase_count, total_revenue)
      SELECT
        product_id,
        SUM(CASE WHEN event_type = 'view' THEN 1 ELSE 0 END) as view_count,
        SUM(CASE WHEN event_type = 'cart' THEN 1 ELSE 0 END) as cart_count,
        SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END) as purchase_count,
        SUM(CASE WHEN event_type = 'purchase' THEN
          CAST(json_extract(properties, '$.price') AS REAL) ELSE 0 END) as total_revenue
      FROM ProductEvent
      GROUP BY product_id`);

    // Update ConversionFunnel
    db.run(`UPDATE ConversionFunnel SET unique_users = 0, total_events = 0`);
    db.run(`UPDATE ConversionFunnel SET
      unique_users = (SELECT COUNT(DISTINCT user_id) FROM ProductEvent WHERE event_type = ConversionFunnel.step),
      total_events = (SELECT COUNT(*) FROM ProductEvent WHERE event_type = ConversionFunnel.step)
      WHERE step IN ('view', 'cart', 'purchase')`);

    // Update HourlyActivity
    db.run(`DELETE FROM HourlyActivity`);
    db.run(`INSERT INTO HourlyActivity (hour, event_type, event_count)
      SELECT
        strftime('%Y-%m-%d %H:00:00', event_ts) as hour,
        event_type,
        COUNT(*) as event_count
      FROM ProductEvent
      GROUP BY strftime('%Y-%m-%d %H:00:00', event_ts), event_type`);

    if (callback) callback();
  });
}

// Ingest endpoint
app.post('/ingest/ProductEvent', (req, res) => {
  const event = req.body;
  const stmt = db.prepare(`INSERT INTO ProductEvent
    (event_id, event_ts, user_id, product_id, event_type, properties)
    VALUES (?, ?, ?, ?, ?, ?)`);

  stmt.run(
    event.event_id,
    event.event_ts,
    event.user_id,
    event.product_id,
    event.event_type,
    JSON.stringify(event.properties)
  );
  stmt.finalize();

  // Update materialized views
  updateViews();

  res.json({ status: 'success', message: 'Event ingested' });
});

// API endpoints
app.get('/top-products', (req, res) => {
  db.all(`SELECT * FROM TopProducts ORDER BY total_revenue DESC`, (err, rows) => {
    if (err) {
      res.status(500).json({ error: err.message });
    } else {
      res.json(rows);
    }
  });
});

app.get('/conversion-funnel', (req, res) => {
  db.all(`SELECT * FROM ConversionFunnel ORDER BY
    CASE
      WHEN step = 'view' THEN 1
      WHEN step = 'cart' THEN 2
      WHEN step = 'purchase' THEN 3
    END`, (err, rows) => {
    if (err) {
      res.status(500).json({ error: err.message });
    } else {
      res.json(rows);
    }
  });
});

app.get('/hourly-activity', (req, res) => {
  db.all(`SELECT * FROM HourlyActivity ORDER BY hour DESC, event_type`, (err, rows) => {
    if (err) {
      res.status(500).json({ error: err.message });
    } else {
      res.json(rows);
    }
  });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy' });
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Analytics pipeline demo server running on port ${PORT}`);
  console.log(`Ingest endpoint: http://localhost:${PORT}/ingest/ProductEvent`);
  console.log(`Top products API: http://localhost:${PORT}/top-products`);
  console.log(`Conversion funnel API: http://localhost:${PORT}/conversion-funnel`);
  console.log(`Hourly activity API: http://localhost:${PORT}/hourly-activity`);
});

module.exports = app;

