let topProducts = {};
let conversionFunnel = { view: { users: new Set(), count: 0 }, cart: { users: new Set(), count: 0 }, purchase: { users: new Set(), count: 0 } };
let hourlyActivity = {};

// Helper function to calculate aggregations
function updateAggregations() {
  // Reset aggregations
  topProducts = {};
  conversionFunnel = { view: { users: new Set(), count: 0 }, cart: { users: new Set(), count: 0 }, purchase: { users: new Set(), count: 0 } };
  hourlyActivity = {};

